#define WOOD_SPECTRUM_RMS_LOG 1
static constexpr const char model_version[]="REAL-RMSLOG-fb6b2bf9d8ef";
static const double rms_target[3]={1.25248937781234498e-01,9.59337002410415030e-02,1.25248937781234498e-01};
static const double log_reference[3]={6.07111834540466268e-04,4.44340182102653369e-04,6.07111834540466268e-04};
static const double log_gain[3]={1.88700871584309435e-03,1.39930440422038923e-03,1.88700871584309435e-03};
inline void preprocess_point(const uint16_t* raw,float* input,int point) {
    uint32_t sum=0; for(int i=0;i<2400;++i) sum+=raw[i];
    float mean=float(sum)/float(2400);
    double energy=0;
    for(int i=0;i<2400;++i) { float t=(float(raw[i])-mean)/2048.0f; energy+=double(t)*double(t); }
    double denominator=std::sqrt(energy/2400.0);
    if(denominator<1e-12) denominator=1e-12;
    const double pi=3.14159265358979323846;
    for(int k=0;k<1201;++k) {
        double re=0,im=0;
        for(int i=0;i<2400;++i) {
            float t=(float(raw[i])-mean)/2048.0f;
            float normalized=float(double(t)*rms_target[point]/denominator);
            double value=double(normalized)*hann[i];
            double angle=2*pi*k*i/2400.0;
            re+=value*std::cos(angle); im-=value*std::sin(angle);
        }
        float magnitude=float(std::sqrt(re*re+im*im)/2400.0);
        input[k]=float(std::log1p(double(magnitude)/log_reference[point])*log_gain[point]);
    }
}

// Ordered inputs P01, P02, P03. Preprocess each hit independently.
// input has 3603 floats; point_scratch has 1201 floats.
inline void preprocess_three(const uint16_t* p1,const uint16_t* p2,const uint16_t* p3,
                             float* input,float* point_scratch) {
    const uint16_t* points[3]={p1,p2,p3};
    for(int p=0;p<3;++p) {
        preprocess_point(points[p],point_scratch,p);
        for(int i=0;i<1201;++i) input[i*3+p]=point_scratch[i];
    }
}
// Use this entry point for direction-independent three-hit classification.
// reverse_input requires 3603 floats, separate from input and scratch.
inline void infer_either_direction(const float* input,float* scores,float* scratch,float* reverse_input) {
    for(int i=0;i<1201;++i) for(int p=0;p<3;++p) reverse_input[i*3+p]=input[i*3+2-p];
    float reversed_scores[2];
    infer(input,scores,scratch); infer(reverse_input,reversed_scores,scratch);
    for(int p=0;p<2;++p) scores[p]=(scores[p]+reversed_scores[p])*0.5f;
}
